@contextmanager
def reraise(errors, into):
    """Reraises errors as other exception.
    If `into` is a callable (not an exception class), calls it with the
    original exception instead of raising."""
    errors = _ensure_exceptable(errors)
    try:
        yield
    except errors as e:
        if callable(into) and not (isinstance(into, type) and issubclass(into, BaseException)):
            into(e)
        else:
            raise_from(into, e)

